const { createRequire } = require('node:module');
const pw = createRequire(require.resolve('@playwright/mcp'))('playwright');
const app = require('./serve.js');

async function runTests() {
  console.log('Starting Gambit Hollow Browser & API Tests...');
  const server = app.listen(3000, '0.0.0.0');

  let browser = null;
  let hasErrors = false;

  try {
    browser = await pw.chromium.launch({
      executablePath: '/usr/local/bin/chromium',
      headless: true,
      args: ['--no-sandbox']
    });

    // Test 1: Desktop Viewport (1280x800) & Initial Load
    console.log('--- Test 1: Desktop Viewport (1280x800) ---');
    const context = await browser.newContext({
      viewport: { width: 1280, height: 800 }
    });
    const page = await context.newPage();

    const consoleErrors = [];
    page.on('console', msg => {
      if (msg.type() === 'error') {
        console.error('Browser Console Error:', msg.text());
        consoleErrors.push(msg.text());
      }
    });
    page.on('pageerror', err => {
      console.error('Page Uncaught Error:', err.message);
      consoleErrors.push(err.message);
    });

    await page.goto('http://localhost:3000');
    await page.waitForSelector('.brand h1');

    // Check no horizontal overflow
    const desktopOverflow = await page.evaluate(() => {
      return document.documentElement.scrollWidth > window.innerWidth;
    });
    console.log('Desktop horizontal overflow:', desktopOverflow);
    if (desktopOverflow) throw new Error('Horizontal overflow detected on desktop');

    // Test 2: Mobile Viewport (375x760)
    console.log('--- Test 2: Mobile Viewport (375x760) ---');
    await page.setViewportSize({ width: 375, height: 760 });
    const mobileOverflow = await page.evaluate(() => {
      return document.documentElement.scrollWidth > window.innerWidth;
    });
    console.log('Mobile horizontal overflow:', mobileOverflow);
    if (mobileOverflow) throw new Error('Horizontal overflow detected on mobile');

    // Reset to desktop for workflow tests
    await page.setViewportSize({ width: 1280, height: 800 });

    // Test 3: Scoring Bench & 29 Hand
    console.log('--- Test 3: Scoring Bench 29-point Hand ---');
    await page.click('#nav-bench');
    await page.waitForSelector('#bench-c1');

    // Set 29 hand: 5S 5H 5D JC with cut 5C
    await page.fill('#bench-c1', '5S');
    await page.fill('#bench-c2', '5H');
    await page.fill('#bench-c3', '5D');
    await page.fill('#bench-c4', 'JC');
    await page.fill('#bench-cut', '5C');
    await page.uncheck('#bench-crib');
    await page.click('#btn-bench-calc');

    await page.waitForSelector('#bench-total-pts');
    const totalText = await page.textContent('#bench-total-pts');
    console.log('Bench Total Result:', totalText);
    if (!totalText.includes('29')) throw new Error('29 hand did not score 29 points!');

    // Test clicking reference hand #1 (29 hand) and #40
    console.log('Testing Reference Hands list click...');
    const refBtns = await page.$$('.ref-item-btn');
    console.log(`Found ${refBtns.length} reference hands in list.`);
    if (refBtns.length !== 40) throw new Error(`Expected 40 reference hands, got ${refBtns.length}`);
    await refBtns[3].click(); // click hand #4 (double run of 3, 14 pts)
    await page.waitForTimeout(200);
    const refTotal = await page.textContent('#bench-total-pts');
    console.log('Reference Hand #4 Total:', refTotal);
    if (!refTotal.includes('14')) throw new Error('Reference hand #4 failed to score 14');

    // Test Pegging Calculator
    console.log('Testing Pegging Calculator...');
    await page.fill('#peg-calc-input', '5S, 6H, TD, TC');
    await page.click('#btn-peg-calc');
    await page.waitForSelector('#peg-calc-result div');
    const pegResultText = await page.textContent('#peg-calc-result');
    console.log('Pegging Calculator Output:', pegResultText);
    if (!pegResultText.includes('31 / 31') || !pegResultText.includes('+4 pts')) {
      throw new Error('Pegging calculator did not return 31 and +4 pts for 5S, 6H, TD, TC');
    }

    // Test 4: Game Workflow (Start game at zero, discard for both seats, play legal card, reload, reopen, play next card)
    console.log('--- Test 4: Full Game Playthrough & Reload Test ---');
    await page.click('#nav-practice');
    await page.waitForSelector('#practice-deal-select');

    // Choose 'pegging' deal for deterministic verification
    await page.selectOption('#practice-deal-select', 'pegging');
    await page.fill('#practice-score-a', '0');
    await page.fill('#practice-score-b', '0');
    await page.click('#btn-start-game');

    // Should switch to Table tab
    await page.waitForSelector('#player-cards-row .card-btn');
    const gameIdTag = await page.textContent('#tag-game-id');
    console.log('Started Game ID:', gameIdTag);

    // Active seat is A (Dealer). Hand for Seat A in 'pegging' deal: 7H, TH, 2S, 3S, 4S, 6D.
    // Discard 2 cards: select first 2 cards or last 2 cards
    console.log('Seat A selecting 2 cards to discard...');
    const seatACardBtns = await page.$$('#player-cards-row .card-btn');
    await seatACardBtns[4].click();
    await seatACardBtns[5].click();
    await page.click('button:has-text("Discard 2 Cards to Crib")');
    await page.waitForTimeout(300);

    // Now switch to Seat B
    console.log('Switching to Seat B...');
    await page.click('#seat-btn-b');
    await page.waitForTimeout(300);
    await page.waitForSelector('#player-cards-row .card-btn');

    // Seat B discards 2 cards
    console.log('Seat B selecting 2 cards to discard...');
    const seatBCardBtns = await page.$$('#player-cards-row .card-btn');
    await seatBCardBtns[4].click();
    await seatBCardBtns[5].click();
    await page.click('button:has-text("Discard 2 Cards to Crib")');
    await page.waitForTimeout(300);

    // Both have discarded: stage should now be PEGGING!
    const stageText = await page.textContent('#tag-stage');
    console.log('Stage after discards:', stageText);
    if (!stageText.includes('PEGGING')) throw new Error('Stage is not PEGGING after discards');

    // Cut card turned: in 'pegging' deal, cut is QC
    const countText = await page.textContent('#count-badge');
    console.log('Initial Pegging Count:', countText);

    // Seat B is non-dealer, so it is Seat B's turn!
    console.log('Seat B playing first legal card (5S)...');
    const bPlayCards = await page.$$('#player-cards-row .card-btn:not([disabled])');
    console.log(`Seat B has ${bPlayCards.length} playable cards.`);
    if (bPlayCards.length === 0) throw new Error('Seat B has no playable cards');
    await bPlayCards[0].click(); // Play 5S
    await page.waitForTimeout(400);

    const countAfter1 = await page.textContent('#count-badge');
    console.log('Count after Seat B played card:', countAfter1);
    if (!countAfter1.includes('5 / 31')) throw new Error(`Expected count 5 / 31, got ${countAfter1}`);

    // Test 5: Reload page and reopen saved game
    console.log('--- Test 5: Reload Page & Reopen Game ---');
    await page.reload();
    await page.waitForSelector('.brand h1');
    await page.waitForTimeout(500);

    // Verify game was reloaded automatically or from Saved Games
    const reloadedGameId = await page.textContent('#tag-game-id');
    console.log('Reloaded Game ID:', reloadedGameId);
    if (reloadedGameId !== gameIdTag) {
      // Reopen from saved games tab
      console.log('Opening from Saved Games tab...');
      await page.click('#nav-saved');
      await page.waitForSelector('.resume-btn');
      await page.click(`.resume-btn[data-id="${gameIdTag}"]`);
      await page.waitForTimeout(300);
    }

    // Switch to Seat A (whose turn it is)
    console.log('Switching to Seat A to play next card...');
    await page.click('#seat-btn-a');
    await page.waitForTimeout(300);

    const turnBadgeText = await page.textContent('#turn-badge');
    console.log('Turn badge for Seat A:', turnBadgeText);
    if (!turnBadgeText.includes('Seat A')) throw new Error(`Expected Seat A turn, got ${turnBadgeText}`);

    // Seat A plays card (e.g. 7H -> count 5 + 7 = 12, or TH -> count 5 + 10 = 15 for 2 pts!)
    console.log('Seat A playing card TH (for fifteen = 2 pts)...');
    const aPlayBtns = await page.$$('#player-cards-row .card-btn:not([disabled])');
    console.log(`Seat A has ${aPlayBtns.length} playable cards.`);
    if (aPlayBtns.length === 0) throw new Error('Seat A has no playable cards');
    await aPlayBtns[1].click(); // TH
    await page.waitForTimeout(400);

    const countAfter2 = await page.textContent('#count-badge');
    const scoreAText = await page.textContent('#score-pts-a');
    console.log('Count after Seat A played:', countAfter2, 'Seat A Score:', scoreAText);

    if (consoleErrors.length > 0) {
      console.error('Errors encountered during test:', consoleErrors);
      hasErrors = true;
    } else {
      console.log('Zero browser console errors encountered throughout all tests!');
    }

    console.log('ALL BROWSER WORKFLOW TESTS PASSED SUCCESSFULLY!');
  } catch (err) {
    console.error('TEST FAILED:', err);
    hasErrors = true;
  } finally {
    if (browser) await browser.close();
    server.close();
  }

  if (hasErrors) {
    process.exit(1);
  }
}

runTests();

